head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldods70002";
scwin.checkVal = false;
scwin.addFile = null;
scwin.delFile = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_attrReals
 * @description 속성 실현 — as-is EL 이 그리던 안내 문구·속성을 컨텍스트 값으로 반영(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_attrReals = function () {
    const attrRealsList = [{ childId: "docpathframe", attr: "src", fn: function () { return "/submission/disclosure.do?method=searchDartFormIframe&mappYn=N&formCd=" + String(dma_formMap.get("formCd")); } }];
    attrRealsList.forEach(function (a) {
        const comp = $c.util.getComponent(a.childId);
        if (!comp) { return; }
        let v;
        try { v = a.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "attrReal:" + a.childId }); return; }
        if (a.attr === "style") {
            String(v).split(";").forEach(function (decl) {
                const kv = decl.split(":");
                if (kv.length === 2 && kv[0].trim()) { comp.setStyle(kv[0].trim(), kv[1].trim()); }
            });
        } else if (a.attr === "label" || a.attr === "__value") {
            if (typeof comp.setValue === "function") { comp.setValue(v); } else if (comp.render) { comp.render.textContent = v; }
        } else if (a.attr === "__items") {
            if (typeof comp.addItem === "function" && v && v.length) {
                if (typeof comp.removeAll === "function") { comp.removeAll(); }
                v.forEach(function (it) { comp.addItem(String(it[0] || ""), String(it[1] || "")); });
            }
        } else if (a.attr === "class") {
            if (comp.render) { comp.render.className = v; }
        } else if (a.attr === "__html") {
            if (comp.render) { comp.render.innerHTML = v; }
        } else if (comp.render) {
            comp.render.setAttribute(a.attr, v);
        }
    });
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("formWrtCautnContn") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {void}
 * @hidden N
 */
scwin.init_pageBody = function () {
    try {
        $('#layer_ban').hide();

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70002.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.addFile = addFile;
        scwin.delFile = delFile;
        scwin.init_rowCopy();
        scwin.init_attrReals();
        scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods70002.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_mpd_files_select_onclick
 * @description 「파일선택」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_mpd_files_select_onclick = function () {
    try { $c.util.onUploadClick($c.util.getComponent('mpd_files'));
    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70002.btn_mpd_files_select_onclick' }); }
};

/**
 * @method
 * @name btn_mpd_files_del_onclick
 * @description 「삭제」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_mpd_files_del_onclick = async function () {
    try { const d = $c.util.getComponent('dlt_files'); const g = $c.util.getComponent('grd_mpd_files'); const u = $c.util.getComponent('mpd_files'); if (!d || !g) { return; } const idx = g.getCheckedIndex ? g.getCheckedIndex('CHK') : []; if (!idx || !idx.length) { return; } for (let i = idx.length - 1; i >= 0; i--) { try { const nm = d.getCellData(idx[i], 'FILE_NM'); if (u && u.removeFile) { u.removeFile(nm); } } catch (_e) { await $c.exception.handleError(_e, { notify: 'none', context: 'mpd_files.del' }); } } if (d.removeRows) { d.removeRows(idx); }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70002.btn_mpd_files_del_onclick' }); }
};

/**
 * @method
 * @name btn_reviewReq_onclick
 * @description 「검토요청」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_reviewReq_onclick = async function(e){
    try {
        await scwin.reviewReq()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70002.btn_reviewReq_onclick' }); }
};

/**
 * @method
 * @name txa_refContn_onkeyup
 * @description txa_refContn 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_refContn_onkeyup = async function(e){
    try {
        await scwin.checkByte($c.util.getComponent("txa_refContn"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70002.txa_refContn_onkeyup' }); }
};

/**
 * @method
 * @name txa_refContn_onchange
 * @description txa_refContn 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.txa_refContn_onchange = async function(e){
    try {
        await scwin.checkByte($c.util.getComponent("txa_refContn"))

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods70002.txa_refContn_onchange' }); }
};

/**
 * @method
 * @name btn_book_onclick
 * @description btn_book 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_book_onclick = function(e){
    try {
        disclsBaseAjax()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70002.btn_book_onclick' }); }
};

/**
 * @method
 * @name btn_related_onclick
 * @description btn_related 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_related_onclick = async function(e){
    try {
        await scwin.fnMappSourcePop('' + dma_formMap.get("formCd") + '','' + dma_formMap.get("formVersion") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70002.btn_related_onclick' }); }
};

/**
 * @method
 * @name btn_ViewSampleDisclosure_onclick
 * @description 「제출공시 샘플보기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_ViewSampleDisclosure_onclick = function(e){
    try {
        scwin.viewSampleDisclosure('' + dma_formMap.get("formCd") + '')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods70002.btn_ViewSampleDisclosure_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_createDoc
 * @description create Doc 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_createDoc = async function () {
    const sbmOptions = {
        id: "tx_createDoc",
        method: "post",
        action: "/submission/formFileUpload.do?method=attachFileUpload",
        ref: "dma_createDocReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

/**
 * @method
 * @name fnOpenPopup
 * @description fn Open Popup 처리
 * @param {*} pageURL pageURL
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnOpenPopup = async function (pageURL) {
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(pageURL), { id: "remoteWin", scrollbars: true, resizable: false, width: "835", height: "695", type: "pageFramePopup" }, { method: "secureDocumentSet", writeTpye: "PREVIEW" });
};

/**
 * @method
 * @name openPopupExample
 * @description open Popup Example 처리
 * @param {String} ipt_formCd ipt_formCd
 * @returns {void}
 * @hidden N
 */
scwin.openPopupExample = async function (ipt_formCd) {
    await scwin.fnOpenPopup('/discls/sample.do?method=exampleList&formCd=' + ipt_formCd);
};

/**
 * @method
 * @name autoResize
 * @description auto Resize 처리
 * @param {*} id id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.autoResize = async function (id) {
    let he;
    let wi;
    if (document.getElementById) {
        he = $c.util.getComponent(id).contentWindow.document.body.scrollHeight;
        wi = $c.util.getComponent(id).contentWindow.document.body.scrollWidth;
    }
    await scwin.dartCreate();
};

async function addFile(obj) {
    let fileCheck = false;
    $("input[type=file]").each(function() {
            if ($(this).val() == null || $(this).val() === '') {
                fileCheck = true;
                return;
            }
    });
    if (fileCheck) {
        await alertE("파일추가는 첨부파일 추가 이후에 가능합니다.");
        return;
    }
    const spanCnt = $(".mt5").length;
    if (spanCnt >= 4) {
        await alertE("첨부파일은 4개까지 첨부 가능합니다.");
        return;
    }
    const tag = '<p class="mt5"><input name="attachFile[' + spanCnt + ']" type="file" style="width: 500px; height: 27px; font-size:13px;"> <input type="button" value="파일추가" onclick="addFile(this);" class="button bt2 small">&nbsp;<input type="button" value="삭제" onclick="delFile(this);" class="button bt2 small"></p>';
    $(obj).parent().after(tag);
}

/**
 * @method
 * @name delFileFirst
 * @description del File First 처리
 * @returns {void}
 * @hidden N
 */
scwin.delFileFirst = function () {
    (console.error('[sdd] 이 화면 문서에 #firstFile 가 없다 — html() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#firstFile")).html('<input name="attachFile[0]" id="attachFile" type="file" style="width: 500px; height: 27px; font-size:13px;" />');
};

function delFile(obj) {
    $(obj).parent().remove();
}

/**
 * @method
 * @name createDoc
 * @description create Doc 처리
 * @param {String} ipt_opnYn ipt_opnYn
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.createDoc = async function (ipt_opnYn) {
    $c.util.getComponent('ipt_opnYn').setValue(ipt_opnYn);
    await scwin.tx_createDoc();
};

/**
 * @method
 * @name fnSecureDocumentSetPopup
 * @description fn Secure Document Set Popup 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSecureDocumentSetPopup = async function () {
    const pageURL = '/jldods70001_create/jldods70001_create.xml';
    await $c.win.openPopup(pageURL, { id: "pop01", scrollbars: true, resizable: false, width: "700", height: "400", type: "pageFramePopup" }, { method: "secureDocumentSet", writeTpye: "PREVIEW" });
};

/**
 * @method
 * @name fnSelectedListShrsPopup
 * @description fn Selected List Shrs Popup 처리
 * @param {String} ipt_formCd ipt_formCd
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSelectedListShrsPopup = async function (ipt_formCd) {
    const pageURL = "/submission/disclosure.do?method=searchListShrsPop&formCd=" + ipt_formCd;
    optVal = scwin.getCenterOpt('700', '380');
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    await $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(pageURL), String((typeof optVal !== 'undefined' ? optVal : '') || '').split(',').reduce(function (o, kv) { const p = kv.split('='); let k = (p[0] || '').replace(/\s/g, ''); const v = (p[1] || '').replace(/\s/g, ''); if (k === 'width' || k === 'height') { o[k] = v; } else if (k === 'scrollbars' || k === 'resizable' || k === 'modal') { o[k] = (v === 'yes' || v === '1'); } return o; }, '' ? Object.assign({ id: "pop02", type: "pageFramePopup" }, { id: '' }) : { id: "pop02", type: "pageFramePopup" }), { method: "secureDocumentSet", writeTpye: "PREVIEW" });
};

/**
 * @method
 * @name fnMappSourcePop
 * @description fn Mapp Source Pop 처리
 * @param {String} ipt_formCd ipt_formCd
 * @param {*} ipt_formVer ipt_formVer
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnMappSourcePop = async function (ipt_formCd, ipt_formVer) {
    const ulr = '/jldods70017/jldods70017.xml';
    scwin.setSelectedDataRecv(await $c.win.openPopup(ulr, { id: "jldods70017", scrollbars: true, resizable: true, width: "835", height: "695", type: "pageFramePopup" }, { method: "searchMappPopInfo", formCd: ipt_formCd, formVersion: ipt_formVer, SCREN_ID: "JLDODS70060", SCREN_PROCES_TP_CD: "01" }));
};

/**
 * @method
 * @name viewSampleDisclosure
 * @description view Sample Disclosure 처리
 * @param {String} ipt_formCd ipt_formCd
 * @returns {void}
 * @hidden N
 */
scwin.viewSampleDisclosure = function (ipt_formCd) {
    const viewSampleDisclosureURL = '/discls/sample.do?method=exampleList&formCd=' + ipt_formCd + '&disclsTitle=';
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(viewSampleDisclosureURL), { id: "remoteWin", scrollbars: true, resizable: true, width: "900", height: "700", type: "pageFramePopup" }, {});
};

/**
 * @method
 * @name getCenterOpt
 * @description get Center Opt 처리
 * @param {*} w w
 * @param {*} h h
 * @returns {void}
 * @hidden N
 */
scwin.getCenterOpt = function (w, h) {
    l = screen.width / 2 - w / 2;
    t = screen.height / 2 - h / 2;
    return "left=" + l + ",top=" + t + ",width=" + w + ",height=" + h + ",scrollbars=no,resizable=no";
};

/**
 * @method
 * @name dartCreate
 * @description dart Create 처리
 * @param {*} applNo applNo
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dartCreate = async function (applNo) {

    if(!scwin.checkVal){
        scwin.checkVal =  true;

        const rtnVal = Object.assign("showDataAlertMsg", (await $c.win.openPopup("/jldods70017/jldods70017.xml?method=showDataAlertMsg", { type: 'pageFramePopup', modal: true, width: '720', height: '380' }, "showDataAlertMsg")) || {});
        if(typeof rtnVal !== "undefined")
        {
            const pageURL = "/submission/disclosure.do?method=searchDartFormIframe&mappYn=Y&formCd="+"${(console.warn(\"[sdd] unresolved:dmap-member:\" + \"formCd @ dma_createDocReq.formCd\"), $c.util.getComponent('dma_createDocReq'))}";
            (document.docpathframe || { elements: [] }).location=pageURL;
            $c.util.getComponent('ipt_mappYn').setValue("Y");

            await scwin.fnSelectedListShrsPopup($c.util.getComponent('ipt_formCd').getValue());

        }
    }

};

/**
 * @method
 * @name reviewReq
 * @description review Req 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reviewReq = async function () {
    if ($c.str.trim($c.util.getComponent('txa_refContn').getValue()) === '') {
        await alertE("전달사항을 입력하십시오.");
        return;
    }
    await scwin.fnReviewPopup();
};

/**
 * @method
 * @name addFileRow
 * @description add File Row 처리
 * @returns {void}
 * @hidden N
 */
scwin.addFileRow = function () { $c.util.onUploadClick($c.util.getComponent('mpd_files')); };

/**
 * @method
 * @name deleteFileRow
 * @description delete File Row 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.deleteFileRow = async function () { if (typeof scwin.btn_mpd_files_del_onclick === 'function') { await scwin.btn_mpd_files_del_onclick(); } };

/**
 * @method
 * @name fnReviewPopup
 * @description fn Review Popup 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnReviewPopup = async function () {
    const pageURL = "/jldods70001_create/jldods70001_create.xml?method=reviewSendInfoPop&isSecureDocumnet=Y&docType=2";
    const isSecureDocumnet = Object.assign("pop01", (await $c.win.openPopup(pageURL, { type: 'pageFramePopup', modal: true, width: '750', height: '320' }, "pop01")) || {});
    if (typeof isSecureDocumnet !== "undefined") {
        await scwin.createDoc('Y');
    }
};

/**
 * @method
 * @name checkByte
 * @description check Byte 처리
 * @param {*} _obj _obj
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkByte = async function (_obj) {
    const standardByte = 4000;
    const contnByte = scwin.getByte(_obj);
    if (contnByte > standardByte) {
        await $c.win.alert((contnByte - standardByte) + "바이트가 초과되었습니다. 초과된 내용은 자동삭제됩니다.\n");
        const contnValue = _obj.getValue();
        _obj.setValue(scwin.calcContn(contnValue, standardByte));
        await scwin.checkByte(_obj);
    }
};

/**
 * @method
 * @name getByte
 * @description get Byte 처리
 * @param {*} _obj _obj
 * @returns {void}
 * @hidden N
 */
scwin.getByte = function (_obj) {
    const sTmpCntnt = new String(_obj.getValue());
    let iCounts = 0;
    for (let i = 0; i < sTmpCntnt.length; i++) {
        const escapeChar = escape(sTmpCntnt.charAt(i));
        if (escapeChar === '%0A') {
            iCounts += 2;
        } else {
            if (escapeChar.length > 4) {
                iCounts += 2;
            } else {
                iCounts++;
            }
        }
    }
    return iCounts;
};

/**
 * @method
 * @name calcContn
 * @description calc Contn 처리
 * @param {*} _contn _contn
 * @param {*} _maximum _maximum
 * @returns {void}
 * @hidden N
 */
scwin.calcContn = function (_contn, _maximum) {
    let rContn = "";
    let nbytes = 0;
    for (let i = 0; i < _contn.length; i++) {
        const ch = _contn.charAt(i);
        let inc = 0;
